const reconStockByClass = `-- name: ReconStockByClass :many

SELECT m.item_class::text AS item_class,
       COALESCE(sum(m.value_delta) FILTER (WHERE m.business_date < $1::date), 0)::numeric AS opening,
       COALESCE(sum(m.value_delta), 0)::numeric AS closing
  FROM inv_movements m
 WHERE m.tenant_id = $2 AND m.property_id = $3 AND m.business_date <= $4::date AND m.item_class IN ('FOOD', 'BEVERAGE')
 GROUP BY m.item_class
`

type ReconStockByClassParams struct {
	FromDate   civil.Date
	TenantID   int64
	PropertyID int64
	ToDate     civil.Date
}

type ReconStockByClassRow struct {
	ItemClass string
	Opening   decimal.Decimal
	Closing   decimal.Decimal
}

// ---------------------------------------------------------------------------------------------------------------------
